using Microsoft.EntityFrameworkCore;
namespace Movers.DAL.Persistence;
public static class JobSchema {
 public static Task Apply(MoversDbContext db) {
 var sql = db.Database.IsSqlServer() ? """
IF OBJECT_ID(N'dbo.TransportJobs', N'U') IS NULL
BEGIN
 CREATE TABLE [TransportJobs] ([SerialNo] int IDENTITY PRIMARY KEY, [Id] uniqueidentifier NOT NULL UNIQUE, [TenantId] uniqueidentifier NOT NULL, [JobNumber] nvarchar(40) NOT NULL, [RequestId] uniqueidentifier NOT NULL, [RequestHash] nvarchar(64) NOT NULL, [DetailsJson] nvarchar(max) NOT NULL, [Status] nvarchar(20) NOT NULL, [Version] uniqueidentifier NOT NULL, [CreatedAtUtc] datetimeoffset NOT NULL, [DepartedAtUtc] datetimeoffset NULL, [ArrivedAtUtc] datetimeoffset NULL);
 CREATE UNIQUE INDEX [IX_TransportJobs_TenantId_JobNumber] ON [TransportJobs] ([TenantId],[JobNumber]);
 CREATE UNIQUE INDEX [IX_TransportJobs_TenantId_RequestId] ON [TransportJobs] ([TenantId],[RequestId]);
END
IF OBJECT_ID(N'dbo.JobCargo', N'U') IS NULL
BEGIN
 CREATE TABLE [JobCargo] ([SerialNo] int IDENTITY PRIMARY KEY, [Id] uniqueidentifier NOT NULL UNIQUE, [TenantId] uniqueidentifier NOT NULL, [JobId] uniqueidentifier NOT NULL, [BoxId] uniqueidentifier NOT NULL, [PickupId] uniqueidentifier NULL, [IsActive] bit NOT NULL, [SnapshotJson] nvarchar(max) NOT NULL, [LoadedBy] nvarchar(160) NOT NULL, [LoadedAtUtc] datetimeoffset NOT NULL, [UnloadedAtUtc] datetimeoffset NULL, [UnloadedBy] nvarchar(320) NULL);
 CREATE UNIQUE INDEX [IX_JobCargo_TenantId_BoxId] ON [JobCargo] ([TenantId],[BoxId]) WHERE [IsActive] = 1;
 CREATE INDEX [IX_JobCargo_TenantId_JobId] ON [JobCargo] ([TenantId],[JobId]);
END
""" : db.Database.IsNpgsql() ? """
CREATE TABLE IF NOT EXISTS "TransportJobs" ("SerialNo" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Id" uuid NOT NULL UNIQUE, "TenantId" uuid NOT NULL, "JobNumber" varchar(40) NOT NULL, "RequestId" uuid NOT NULL, "RequestHash" varchar(64) NOT NULL, "DetailsJson" text NOT NULL, "Status" varchar(20) NOT NULL, "Version" uuid NOT NULL, "CreatedAtUtc" timestamp with time zone NOT NULL, "DepartedAtUtc" timestamp with time zone NULL, "ArrivedAtUtc" timestamp with time zone NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_TransportJobs_TenantId_JobNumber" ON "TransportJobs" ("TenantId","JobNumber");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_TransportJobs_TenantId_RequestId" ON "TransportJobs" ("TenantId","RequestId");
CREATE TABLE IF NOT EXISTS "JobCargo" ("SerialNo" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Id" uuid NOT NULL UNIQUE, "TenantId" uuid NOT NULL, "JobId" uuid NOT NULL, "BoxId" uuid NOT NULL, "PickupId" uuid NULL, "IsActive" boolean NOT NULL, "SnapshotJson" text NOT NULL, "LoadedBy" varchar(160) NOT NULL, "LoadedAtUtc" timestamp with time zone NOT NULL, "UnloadedAtUtc" timestamp with time zone NULL, "UnloadedBy" varchar(320) NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_JobCargo_TenantId_BoxId" ON "JobCargo" ("TenantId","BoxId") WHERE "IsActive" = true;
CREATE INDEX IF NOT EXISTS "IX_JobCargo_TenantId_JobId" ON "JobCargo" ("TenantId","JobId");
""" : """
CREATE TABLE IF NOT EXISTS "TransportJobs" ("SerialNo" INTEGER PRIMARY KEY AUTOINCREMENT, "Id" TEXT NOT NULL UNIQUE, "TenantId" TEXT NOT NULL, "JobNumber" TEXT NOT NULL, "RequestId" TEXT NOT NULL, "RequestHash" TEXT NOT NULL, "DetailsJson" TEXT NOT NULL, "Status" TEXT NOT NULL, "Version" TEXT NOT NULL, "CreatedAtUtc" TEXT NOT NULL, "DepartedAtUtc" TEXT NULL, "ArrivedAtUtc" TEXT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_TransportJobs_TenantId_JobNumber" ON "TransportJobs" ("TenantId","JobNumber");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_TransportJobs_TenantId_RequestId" ON "TransportJobs" ("TenantId","RequestId");
CREATE TABLE IF NOT EXISTS "JobCargo" ("SerialNo" INTEGER PRIMARY KEY AUTOINCREMENT, "Id" TEXT NOT NULL UNIQUE, "TenantId" TEXT NOT NULL, "JobId" TEXT NOT NULL, "BoxId" TEXT NOT NULL, "PickupId" TEXT NULL, "IsActive" INTEGER NOT NULL, "SnapshotJson" TEXT NOT NULL, "LoadedBy" TEXT NOT NULL, "LoadedAtUtc" TEXT NOT NULL, "UnloadedAtUtc" TEXT NULL, "UnloadedBy" TEXT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_JobCargo_TenantId_BoxId" ON "JobCargo" ("TenantId","BoxId") WHERE "IsActive" = 1;
CREATE INDEX IF NOT EXISTS "IX_JobCargo_TenantId_JobId" ON "JobCargo" ("TenantId","JobId");
""";
 return db.Database.ExecuteSqlRawAsync(sql);
 }
}
